//
// Shared by the generated documentation tests. Each test calls `run` with one
// transcript command and, when the docs show output, the expected stdout.
#![allow(dead_code)]

use std::path::PathBuf;
use std::process::Command;

/// The repository root, three levels above `crates/pqbench-cli`.
fn root() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("..")
        .join("..")
        .canonicalize()
        .expect("repository root")
}

/// Run one documented command and assert it succeeds.
///
/// The command runs through `sh -c` with the working directory at the
/// repository root, so the paths the docs use resolve. `CARGO_BIN_EXE_pqbench`
/// is the directory holding the built binary; prepending it to `PATH` means a
/// documented `pqbench ...` line runs the build under test rather than any
/// installed copy, and a pipe or `xargs` finds it too.
///
/// `line` is the source line of the command, used in the failure message.
///
/// `expected` is the output the transcript documents, or `None` when the block
/// only shows the command. When present, the command's combined stdout+stderr
/// must match it line for line after normalization.
#[track_caller]
pub fn run(command: &str, line: usize, expected: Option<&[&str]>) {
    let binary = PathBuf::from(env!("CARGO_BIN_EXE_pqbench"));
    let binary_directory = binary.parent().expect("binary has a parent");

    let path = std::env::var_os("PATH").unwrap_or_default();
    let mut paths = vec![binary_directory.to_path_buf()];
    paths.extend(std::env::split_paths(&path));
    let path = std::env::join_paths(paths).expect("a valid PATH");

    let output = Command::new("sh")
        .arg("-c")
        .arg(command)
        .current_dir(root())
        .env("PATH", path)
        .output()
        .unwrap_or_else(|error| panic!("line {line}: could not run `{command}`: {error}"));

    assert!(
        output.status.success(),
        "line {line}: `{command}` failed with {status}\n--- stdout ---\n{stdout}\n--- stderr ---\n{stderr}",
        status = output.status,
        stdout = String::from_utf8_lossy(&output.stdout),
        stderr = String::from_utf8_lossy(&output.stderr),
    );

    let Some(expected) = expected else {
        return;
    };
    // Compare the combined output: a transcript shows what the user sees, and a
    // command that writes NDJSON to stdout or a status line to stderr is
    // documented the same way. Only one stream is non-empty in practice.
    let combined = format!(
        "{}{}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    let actual = normalize(&combined);
    assert!(
        actual.len() == expected.len()
            && actual.iter().zip(expected).all(|(line, want)| line == want),
        "line {line}: `{command}` output did not match the docs\n--- documented ---\n{documented}\n--- actual ---\n{actual}",
        documented = expected.join("\n"),
        actual = actual.join("\n"),
    );
}

/// Normalize captured output: drop trailing whitespace per line, the final
/// blank line, and replace the repository root's absolute path with `<root>`,
/// so a transcript is insensitive to incidental spacing and to where the
/// checkout lives.
fn normalize(stdout: &str) -> Vec<String> {
    let root = root().display().to_string();
    let mut lines: Vec<String> = stdout
        .lines()
        .map(|line| line.trim_end().replace(&root, "<root>"))
        .collect();
    while lines.last().is_some_and(|line| line.is_empty()) {
        lines.pop();
    }
    lines
}
